{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Cilomilast, the closest retrieved analogue, had a mean absolute oral bioavailability of 96% (range 92–102%) in healthy humans after oral solution vs iv infusion; its cyclohexanecarbonitrile-aryl-carboxylic acid core is shared with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Pethidine, a phenylpiperidine with a basic amine, showed mean oral bioavailability of 0.52 ± 0.07 in humans, supporting that the query's phenylpiperidine scaffold can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Milnacipran, a polar basic-amine drug with an aromatic ring, had an absolute oral bioavailability of 85 ± 3% in humans, indicating that ionizable amine-containing structures can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alvimopan, a zwitterionic piperidine carboxylic acid, had an absolute oral bioavailability of only 6% in humans; this is the main contradictory evidence, but its lower similarity and peripheral-antagonist design reduce transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the closest analogue cilomilast has near-complete human absolute bioavailability and shares the cyclohexanecarbonitrile-aryl-carboxylic acid scaffold; additional basic/piperidine drugs such as pethidine and milnacipran also exceed 20%. Alvimopan's 6% F is a lower-similarity counterexample whose low absorption is tied to its peripheral-antagonist design.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "No retrieved analogue combines the query's cyclohexanecarbonitrile-fluorophenyl and piperidine-carboxylic acid zwitterion in a single structure; transfer relies on separate analogues.",
    "Permeability, efflux, and first-pass metabolism data for the query are unavailable, so the impact of its zwitterionic character remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

